data.response:
# Les boucles en Delphi - Tous les types

## **1. FOR classique (avec entier)**

```delphi
// Boucle croissante
for i := 1 to 10 do
begin
  ShowMessage(IntToStr(i));
end;

// Boucle décroissante
for i := 10 downto 1 do
begin
  ShowMessage(IntToStr(i));
end;
```

---

## **2. WHILE (tant que)**

```delphi
var
  i: Integer;
begin
  i := 1;
  while i <= 10 do
  begin
    ShowMessage(IntToStr(i));
    Inc(i);  // i := i + 1
  end;
end;
```

---

## **3. REPEAT...UNTIL (répéter jusqu'à)**

```delphi
var
  i: Integer;
begin
  i := 1;
  repeat
    ShowMessage(IntToStr(i));
    Inc(i);
  until i > 10;
  // La condition est testée À LA FIN (au moins 1 exécution garantie)
end;
```

---

## **4. FOR...IN (boucle sur collection)**

```delphi
// Sur un tableau
var
  arr: array of Integer;
  value: Integer;
begin
  SetLength(arr, 3);
  arr[0] := 10;
  arr[1] := 20;
  arr[2] := 30;

  for value in arr do
    ShowMessage(IntToStr(value));
end;

// Sur une liste (TList)
var
  list: TList<Integer>;
  value: Integer;
begin
  list := TList<Integer>.Create;
  try
    list.Add(10);
    list.Add(20);
    list.Add(30);

    for value in list do
      ShowMessage(IntToStr(value));
  finally
    list.Free;
  end;
end;

// Sur les clés d'un dictionnaire
var
  dict: TDictionary<string, Integer>;
  key: string;
begin
  dict := TDictionary<string, Integer>.Create;
  try
    dict.Add('A', 1);
    dict.Add('B', 2);

    for key in dict.Keys do
      ShowMessage(key);
  finally
    dict.Free;
  end;
end;
```

---

## **5. FOR...IN sur les valeurs d'une collection**

```delphi
var
  dict: TDictionary<string, Integer>;
  value: Integer;
begin
  dict := TDictionary<string, Integer>.Create;
  try
    dict.Add('A', 1);
    dict.Add('B', 2);

    // Boucler sur les valeurs
    for value in dict.Values do
      ShowMessage(IntToStr(value));
  finally
    dict.Free;
  end;
end;
```

---

## **6. FOR avec pas personnalisé (pas standard, à coder manuellement)**

```delphi
// Pas de 2
var
  i: Integer;
begin
  i := 0;
  while i <= 20 do
  begin
    ShowMessage(IntToStr(i));
    i := i + 2;  // Pas de 2
  end;
end;

// Ou avec FOR classique (plus verbeux)
var
  i: Integer;
begin
  for i := 0 to 10 do
  begin
    ShowMessage(IntToStr(i * 2));  // Affiche 0, 2, 4, 6...
  end;
end;
```

---

## **7. Contrôle de boucle: BREAK et CONTINUE**

```delphi
var
  i: Integer;
begin
  for i := 1 to 20 do
  begin
    if i = 5 then
      Continue;  // Saute cette itération

    if i = 15 then
      Break;  // Quitte la boucle

    ShowMessage(IntToStr(i));
  end;
end;
```

---

## **8. Boucles imbriquées**

```delphi
var
  i, j: Integer;
begin
  for i := 1 to 3 do
  begin
    for j := 1 to 3 do
    begin
      ShowMessage(Format('i=%d, j=%d', [i, j]));
    end;
  end;
end;
```

---

## **9. FOR sur une chaîne de caractères**

```delphi
var
  s: string;
  c: Char;
begin
  s := 'Bonjour';

  for c in s do
    ShowMessage(c);
end;
```

---

## **Comparaison rapide:**

| Type | Quand l'utiliser |
|------|-----------------|
| **FOR** | Quand tu connais le nombre d'itérations |
| **WHILE** | Quand tu ne sais pas combien, condition testée au début |
| **REPEAT...UNTIL** | Quand tu dois exécuter au moins 1 fois |
| **FOR...IN** | Quand tu boucles sur une collection/tableau |

---

Voilà! Des questions sur un type spécifique? 🎯

